import {RES,COST,isSetup,canPay,total,emptyResources,legalSettlements,legalSetupRoads,legalRoads,legalCities,adjacent,tradeRatio,mayTrade,mayPlayDev,tradeRecipient,applyAction,observe} from './game.js?v=780fbcd3e213';

// Decisions accept observations, never authoritative game state.
function tieRandom(v){let x=(v.turn*2654435761+v.eventId*2246822519+v.me*3266489917)>>>0;return()=>{x^=x<<13;x^=x>>>17;x^=x<<5;return(x>>>0)/4294967296;};}
export function vertexValue(v,id,p=v.me){const node=v.vertices[id],types=new Set();let value=0;for(const tid of node.tiles){const t=v.tiles[tid];if(t.type==='desert')continue;types.add(t.type);value+=(6-Math.abs(7-t.number))*(t.type==='wheat'?1.15:t.type==='ore'?1.06:1);}const owned=new Set(v.vertices.filter(n=>n.owner===p).flatMap(n=>n.tiles.map(tid=>v.tiles[tid].type)));return value+types.size*1.2+[...types].filter(r=>!owned.has(r)).length*1.7;}
function goal(v){const p=v.players[v.me];if(legalCities(v,v.me).length&&(p.resources.ore>=2||!legalRoads(v,v.me).length))return COST.city;if(legalSettlements(v,v.me).length)return COST.settlement;if(legalRoads(v,v.me).length)return COST.road;if(legalCities(v,v.me).length)return COST.city;return COST.dev;}
function resourceValue(v,r,resources=v.players[v.me].resources){const needed=goal(v)[r]??0;return resources[r]<needed?3.6:resources[r]===needed&&needed>0?1.7:resources[r]>=4?.65:1;}
function bestRoad(v,rng){const me=v.me;return legalRoads(v,me).map(id=>{const e=v.edges[id];let score=0;for(const vid of[e.a,e.b]){const node=v.vertices[vid];if(node.owner!==null)continue;const nearby=[node,...adjacent(v,node)];for(const n of nearby){if(n.owner===null&&adjacent(v,n).every(a=>a.owner===null))score=Math.max(score,vertexValue(v,n.id)-(n.id===node.id?0:3));}}return{id,score:score+rng()};}).sort((a,b)=>b.score-a.score)[0];}
export function bestRobberTile(v){return v.tiles.filter(t=>t.id!==v.robber).map(t=>{const production=t.number?6-Math.abs(7-t.number):0;let score=0;for(const id of t.vertices){const n=v.vertices[id];if(n.owner===null)continue;score+=n.owner===v.me?-12*n.level:n.level*(1+v.players[n.owner].publicScore*.2);}return{id:t.id,score:score*production};}).sort((a,b)=>b.score-a.score)[0].id;}
function monopolyChoice(v){return RES.map(r=>{let expected=0;for(const node of v.vertices){if(node.owner===null||node.owner===v.me)continue;for(const tid of node.tiles){const t=v.tiles[tid];if(t.type===r)expected+=node.level*(6-Math.abs(7-t.number));}}return{r,score:expected+.6*resourceValue(v,r)};}).sort((a,b)=>b.score-a.score)[0].r;}
function development(v,preRoll=false){if(!mayPlayDev(v,v.me))return null;const cards=v.players[v.me].dev.filter(c=>c.type!=='point'&&c.bought<v.turn);for(const c of cards){if(preRoll&&c.type!=='knight')continue;const action={type:'dev',id:c.id};if(c.type==='roads'&&!legalRoads(v,v.me).length)continue;if(c.type==='plenty'){const supply={...v.bank},holding={...v.players[v.me].resources};action.resources=[];for(let i=0;i<2;i++){const r=RES.filter(r=>supply[r]>0).sort((a,b)=>resourceValue(v,b,holding)-resourceValue(v,a,holding))[0];if(!r)break;action.resources.push(r);supply[r]--;holding[r]++;}}if(c.type==='monopoly')action.resource=monopolyChoice(v);return action;}return null;}
function respond(v){const o=v.offer,me=v.me,p=v.players[me],mine=me===o.from?o.give:o.get,receive=me===o.from?o.get:o.give;if(!canPay(p,mine))return{type:'respond',accept:false};let gain=0,loss=0;for(const r of RES){gain+=(receive[r]??0)*resourceValue(v,r);loss+=(mine[r]??0)*resourceValue(v,r);}if(gain>=loss*.95)return{type:'respond',accept:true};const already=v.logs.some(e=>e.player===me&&e.turn===v.turn&&e.kind==='trade-counter');if(!already){const wanted=RES.filter(r=>receive[r]>0).sort((a,b)=>resourceValue(v,b)-resourceValue(v,a))[0];if(wanted&&receive[wanted]<3){const give={...o.give},get={...o.get},pack=me===o.from?get:give;pack[wanted]=(pack[wanted]??0)+1;return{type:'counter',give,get};}}return{type:'respond',accept:false};}
function offer(v){if(!mayTrade(v,v.me)||v.logs.some(e=>e.player===v.me&&e.turn===v.turn&&e.kind==='trade-offer'))return null;const p=v.players[v.me],needed=goal(v),want=RES.filter(r=>p.resources[r]<(needed[r]??0)),spare=RES.filter(r=>p.resources[r]>(needed[r]??0)).sort((a,b)=>(p.resources[b]-(needed[b]??0))-(p.resources[a]-(needed[a]??0)));if(!want.length||!spare.length)return null;const targets=v.players.filter(q=>q.id!==v.me&&q.resourceCount>0);if(!targets.length)return null;const target=targets.sort((a,b)=>{const likelihood=q=>v.vertices.filter(n=>n.owner===q.id).reduce((sum,n)=>sum+n.tiles.filter(tid=>v.tiles[tid].type===want[0]).length,0);return likelihood(b)-likelihood(a);})[0];return{type:'offer',with:target.id,give:{[spare[0]]:1},get:{[want[0]]:1}};}
export function chooseAction(v){
 const me=v.me,p=v.players[me],rng=tieRandom(v);if(v.phase==='over')return null;
 if(v.phase==='discard'){let left=v.discardRequired[me];if(!left)return null;const resources=emptyResources(),holding={...p.resources},wanted=goal(v);while(left-->0){const r=RES.filter(r=>holding[r]>0).sort((a,b)=>(holding[b]-(wanted[b]??0))-(holding[a]-(wanted[a]??0)))[0];resources[r]++;holding[r]--;}return{type:'discard',resources};}
 if(v.offer)return tradeRecipient(v.offer)===me?respond(v):null;
 if(v.current!==me)return null;
 if(isSetup(v)){if(v.phase==='setup-settlement'){const id=legalSettlements(v,me,true).map(id=>({id,score:vertexValue(v,id)+rng()*2})).sort((a,b)=>b.score-a.score)[0]?.id;return id===undefined?null:{type:'settlement',id};}const choices=legalSetupRoads(v,me).map(id=>{const e=v.edges[id],node=v.vertices[e.a===v.setupVertex?e.b:e.a],future=adjacent(v,node).filter(n=>n.owner===null&&adjacent(v,n).every(a=>a.owner===null));return{id,score:Math.max(0,...future.map(n=>vertexValue(v,n.id)))+rng()};}).sort((a,b)=>b.score-a.score);return choices.length?{type:'road',id:choices[0].id}:null;}
 if(v.phase==='robber')return{type:'robber',tile:bestRobberTile(v)};
 if(v.phase==='victim'){const id=[...v.pendingVictims].sort((a,b)=>v.players[b].resourceCount-v.players[a].resourceCount)[0];return{type:'victim',player:id};}
 if(v.phase==='road-building'){const road=bestRoad(v,rng);return road?{type:'road',id:road.id}:null;}
 if(v.phase==='roll')return development(v,true)??{type:'roll'};
 if(v.phase!=='build')return null;
 const dev=development(v);if(dev)return dev;
 const cities=legalCities(v,me);if(cities.length&&canPay(p,COST.city))return{type:'city',id:cities.sort((a,b)=>vertexValue(v,b)-vertexValue(v,a))[0]};
 const villages=legalSettlements(v,me);if(villages.length&&canPay(p,COST.settlement))return{type:'settlement',id:villages.sort((a,b)=>vertexValue(v,b)-vertexValue(v,a))[0]};
 const road=bestRoad(v,rng);if(road&&canPay(p,COST.road)&&road.score>1)return{type:'road',id:road.id};
 const wanted=goal(v),missing=RES.filter(r=>p.resources[r]<(wanted[r]??0)&&v.bank[r]>0),surplus=RES.filter(r=>p.resources[r]-(wanted[r]??0)>=tradeRatio(v,me,r));
 if(mayTrade(v,me)&&missing.length&&surplus.length)return{type:'bank',give:surplus[0],get:missing[0]};
 if(v.deckCount&&canPay(p,COST.dev))return{type:'buyDev'};
 return offer(v)??{type:'end'};
}
export function aiTurn(s,p=s.current){const initialSetup=isSetup(s),setupIndex=s.setupIndex;for(let i=0;i<36;i++){const view=observe(s,p),action=chooseAction(view);if(!action)break;const result=applyAction(s,p,action);if(!result.ok)break;if(s.phase==='over'||(initialSetup&&s.setupIndex!==setupIndex))break;if(s.phase==='discard'&&!s.discardRequired[p])break;if(s.offer&&tradeRecipient(s.offer)!==p)break;if(s.phase!=='discard'&&!s.offer&&s.current!==p)break;}return s;}
